import os
import sys
import threading
import tkinter as tk
import customtkinter as ctk
from tkinterdnd2 import TkinterDnD, DND_FILES
from tkinter import filedialog
from PIL import Image, ImageDraw
import base64
import tempfile
import webbrowser


PROGRAM_ADI = "EXIF Yok Edici 3000"
PROGRAM_SURUMU = "1.1"
PROGRAM_GELISTIRICI = "tyyaman"
GELISTIRICI_BAGLANTISI = "https://github.com/tyyaman55"

DESTEKLENEN_UZANTILAR = {".jpg", ".jpeg", ".png", ".gif", ".bmp", ".tiff", ".tif"}

FORMAT_ESLEME = {
    ".jpg": "JPEG",
    ".jpeg": "JPEG",
    ".png": "PNG",
    ".gif": "GIF",
    ".bmp": "BMP",
    ".tiff": "TIFF",
    ".tif": "TIFF",
}

SIMGE_TABAN64 = """"""


def boyut_formatla(bayt):
    if bayt < 1024:
        return f"{bayt} B"
    elif bayt < 1024 * 1024:
        return f"{bayt / 1024:.1f} KB"
    return f"{bayt / (1024 * 1024):.1f} MB"


class SurukleBirakPencere(ctk.CTk, TkinterDnD.DnDWrapper):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.TkdndVersion = TkinterDnD._require(self)


class ExifYokEdiciUygulama:
    def __init__(self, pencere):
        self.pencere = pencere
        self.pencere.title(PROGRAM_ADI)
        self.pencere.geometry("520x480")
        self.pencere.minsize(420, 400)
        ctk.set_appearance_mode("system")
        ctk.set_default_color_theme("blue")

        self.simge_yolu, self.gecici_simge_mi = self.simge_hazirla()
        if self.simge_yolu and os.path.exists(self.simge_yolu):
            try:
                self.pencere.iconbitmap(self.simge_yolu)
                self.pencere.after(200, lambda: self.pencere.iconbitmap(self.simge_yolu))
            except Exception:
                pass

        self.unlem_ico_yolu = ""
        self.unlem_simgesi_hazirla()

        self.dosyalar = []
        self.satir_widgetleri = []
        self.cikti_klasoru = ""
        self.islem_devam_ediyor = False
        self.acilir_menu = None
        self.arayuz_kur()

    def simge_hazirla(self):
        dizinler = [
            getattr(sys, "_MEIPASS", ""),
            os.path.dirname(os.path.abspath(__file__)),
            os.getcwd(),
        ]
        for dizin in dizinler:
            if dizin:
                aday_yol = os.path.join(dizin, "exif_yok_edici_3000.ico")
                if os.path.isfile(aday_yol):
                    return aday_yol, False
        try:
            gecici_dizin = tempfile.gettempdir()
            gecici_yol = os.path.join(gecici_dizin, "exif_yok_edici_simge.ico")
            with open(gecici_yol, "wb") as cikti:
                cikti.write(base64.b64decode(SIMGE_TABAN64))
            return gecici_yol, True
        except Exception:
            return "", False

    def unlem_simgesi_hazirla(self):
        try:
            gorsel = Image.new("RGBA", (64, 64), (0, 0, 0, 0))
            cizim = ImageDraw.Draw(gorsel)
            cizim.ellipse((2, 2, 61, 61), fill="#d32f2f")
            cizim.rounded_rectangle((28, 14, 35, 38), radius=3, fill="white")
            cizim.ellipse((28, 43, 35, 50), fill="white")

            gecici_dizin = tempfile.gettempdir()
            ico_yolu = os.path.join(gecici_dizin, "exif_yok_edici_unlem.ico")
            gorsel.save(ico_yolu, format="ICO", sizes=[(16, 16), (32, 32), (48, 48), (64, 64)])
            self.unlem_ico_yolu = ico_yolu
        except Exception:
            self.unlem_ico_yolu = ""

